import 'package:dart_basics_tepenchak/models/university.dart';
void main() { print('=== University Management System Demo ==='); runUniversityDemo(); }
void runUniversityDemo() { final university=University(name:'Kyiv Demo University'); final professor=Professor(id:'P1',firstName:'Olena',lastName:'Koval',birthDate:DateTime(1980,5,10),department:'Computer Science',salary:30000); university.professors.add(professor); final dart=Course(id:'DART',name:'Dart Basics',description:'Language basics',credits:3,instructor:professor.fullName); final flutter=Course(id:'FLUTTER',name:'Flutter',description:'Mobile UI',credits:4,instructor:professor.fullName,prerequisites:['DART']); university.courses.addAll([dart,flutter]); professor.assignCourse('DART'); final s1=Student(id:'S1',firstName:'Serhii',lastName:'Tepenchak',birthDate:DateTime(1999,10,10),skills:['Dart','Git']); final s2=Student(id:'S2',firstName:'Anna',lastName:'Bondar',birthDate:DateTime(2000,3,12),skills:['Flutter','Git']); university.addStudent(s1); university.addStudent(s2); s1.enrollInCourse('DART'); s1.addGrade('DART',92); s2.enrollInCourse('DART'); s2.addGrade('DART',74); print(professor); print('Students: ${university.students}'); print('DART students: ${university.getStudentsByCourse('DART').map((s)=>s.fullName).toList()}'); print('Available for S1: ${university.getAvailableCoursesForStudent('S1')}'); print('Student JSON: ${s1.toJson()}'); print('Restored: ${Student.fromJson(s1.toJson())}'); print('Statistics: ${university.generateStatistics()}'); university.removeStudent('S2'); print('After CRUD delete: ${university.students.length} student'); }
